effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

   /////////////////////////

    #define PI 3.1415926

    float rand(float t)
    {
        return fract(sin(dot(vec2(t,t) ,vec2(12.9898,78.233))) * 43758.5453);
    }

    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;
    	vec4 result;

    	float time= progressa;

        vec2 TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;
        TanRyu /= scale;
        // TanRyu /= (position.z/100.);
        TanRyu += vec2(-395.0+position.x,190.0+position.y)*vec2(-1.,1.)/500.;
        // TanRyu += position*vec2(-1.,1.)/500.;

    	vec2 uv = TanRyu;

     	vec2 uv1=uv-vec2(0.8, 0.4);
        float r = length(uv1)*111.0;

        float t = ceil(r);
        float a = fract(atan(uv1.y, uv1.x)/PI+time*rand(t)*.1 +t*0.1);

        float ang = rand(t);
        float c = smoothstep(ang,ang-1.5,a*progressb) ;

        vec3 col = vec3(color.rgb)*3.;
        float rr = length(uv-vec2(0.6,1.4))-0.8;
    	vec3 coll=vec3(0.0);

        coll=mix(coll,col*rand(t),c*step(0.1,r/111.));

        result = vec4(coll,1.0);

    	vec4 factor = mix(texColorX,result,alpha);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = resultfinal;
    }
